test-code.code:
class BadLowercase(private val name: String) {
    override fun equals(other: Any?): Boolean {
        return other is BadLowercase && name.lowercase() == other.name.lowercase()
    }

    override fun hashCode(): Int {
        return name.hashCode()
    }
}

class GoodLowercase(private val name: String) {
    override fun equals(other: Any?): Boolean {
        return other is GoodLowercase && name.lowercase() == other.name.lowercase()
    }

    override fun hashCode(): Int {
        return name.lowercase().hashCode()
    }
}
